import React, { useEffect, useState } from "react";
import { 
  MapContainer, 
  TileLayer, 
  CircleMarker, 
  Popup, 
  Circle, 
  useMap 
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para ajustar la vista del mapa
const ChangeView = ({ coordenadas }) => {
  const map = useMap();
  
  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7);
    }
  }, [coordenadas, map]);
  
  return null;
};

// Componente de mapa con tema claro
const LightMap = ({ coordenadas, circleScale, opacity }) => (
  <MapContainer 
    center={[23.6345, -102.5528]}
    zoom={5} 
    style={{ height: "100vh", width: "100%" }}
  >
    <TileLayer 
      url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
    />
    <ChangeView coordenadas={coordenadas} />
    
    {coordenadas && (
      <>
        <CircleMarker
          center={[coordenadas.lat, coordenadas.lng]}
          radius={10}
          color="red"
          fillColor="red"
          fillOpacity={0.7}
        >
          <Popup>
            <b>Ubicación del Sismo</b> <br />
            Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
          </Popup>
        </CircleMarker>

        <Circle
          center={[coordenadas.lat, coordenadas.lng]}
          radius={circleScale * 50000}
          color="red"
          fillColor="red"
          fillOpacity={opacity}
          stroke={false}
        />
      </>
    )}
  </MapContainer>
);

// Componente de mapa con tema oscuro
const DarkMap = ({ coordenadas, circleScale, opacity }) => (
  <MapContainer 
    center={[23.6345, -102.5528]}
    zoom={5} 
    style={{ height: "100vh", width: "100%" }}
  >
    <TileLayer 
      url="https://tiles.stadiamaps.com/tiles/alidade_smooth_dark/{z}/{x}/{y}{r}.png"
    />
    <ChangeView coordenadas={coordenadas} />
    
    {coordenadas && (
      <>
        <CircleMarker
          center={[coordenadas.lat, coordenadas.lng]}
          radius={10}
          color="red"
          fillColor="red"
          fillOpacity={0.7}
        >
          <Popup>
            <b>Ubicación del Sismo</b> <br />
            Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
          </Popup>
        </CircleMarker>

        <Circle
          center={[coordenadas.lat, coordenadas.lng]}
          radius={circleScale * 50000}
          color="red"
          fillColor="red"
          fillOpacity={opacity}
          stroke={false}
        />
      </>
    )}
  </MapContainer>
);

// Componente principal que decide qué mapa mostrar
const MapaMexico = ({ coordenadas, theme }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  useEffect(() => {
    if (!coordenadas) return;

    setCircleScale(1); 
    setOpacity(0.6);

    const interval = setInterval(() => {
      setCircleScale((prev) => prev + 0.05);
      setOpacity((prev) => Math.max(prev - 0.01, 0));

      if (circleScale > 3 || opacity <= 0) {
        setCircleScale(1);
        setOpacity(0.6);
      }
    }, 50);

    return () => clearInterval(interval); 
  }, [coordenadas, circleScale, opacity]);

  // Renderizado condicional basado en el tema
  return theme === "dark" ? (
    <DarkMap 
      coordenadas={coordenadas} 
      circleScale={circleScale} 
      opacity={opacity} 
    />
  ) : (
    <LightMap 
      coordenadas={coordenadas} 
      circleScale={circleScale} 
      opacity={opacity} 
    />
  );
};

export default MapaMexico;
